nil,
nil,
},
[86791] = { en="Missing Blackmaw Scouts", ai=true,
[===[Зниклі розвідники Чорнопащих]===],
[===[Нещодавно я відправив загін розвідників, щоб зібрати відомості про твердиню Леґаші і, можливо, знайти нашого ватага. Вони досі не повернулися. Я починаю боятися найгіршого.

На схід звідси в Леґаші багато таборів. Якщо хтось із загону ще живий, то він, найімовірніше, десь там поблизу.]===],
[===[Знайдіть розвідувальний загін Чорнопащих біля таборів Леґаші на схід від Урсолану.]===],
