},
[86814] = { en="Blackmaw Counter-Offensive", ai=true,
[===[Контрнаступ Чорнопащих]===],
[===[Я негайно відправлю підкріплення в Урсолан.

Візьми цей стяг. Коли будеш {стать:готовий:готова} до бою з Халаноксом, встанови стяг у його демонічному колі виклику. Це розлютить його і стане для наших воїнів сигналом до атаки.

Коли Халанокса буде здолано, повідом про це хранителя брами Люторева.]===],
[===[Встановіть бойовий стяг Деревопузих у твердині Леґаші, що в Азшарі. Вбийте принца Халанокса і доповідайте про перемогу хранителю брами Люторевові в Урсолані.]===],
nil,
nil,
},
[86925] = { en="Toil and Trouble", ai=true,
[===[Труд і клопіт]===],
[===[Схоже, в цьому казані можна зварити огневицю, яку шукає старійшина Тернохруст.

Якби ж ви тільки знали як. Напевно, хтось із сатирів у таборі Леґаші має при собі рецепт.]===],
[===[Здобудьте рецепт огневиці Леґаші в сатирів з табору Леґаші.]===],
nil,
nil,
},
[86926] = { en="Felfire Burn, Cauldron Bubble", ai=true,
[===[Гори, вогню скверни, кипи, котле]===],
[===[У рецепті написано:

Паросль пекла ти нарви,
П'ять пучків її візьми,
Змішай із крихтою демонської сили —
Й зажене їх у могили.]===],
[===[Принесіть 5 сатириній і крихту скверни до котла Леґаші в таборі Леґаші.]===],
nil,
nil,
},
[86927] = { en="Running Firewater", ai=true,
[===[Проточна огневиця]===],
[===[Щойно сатиринія та крихта скверни плюхаються в киплячу рідину, над нею здіймається клуб їдкого газу.

Краще затисніть носа, швиденько наберіть зразок і віднесіть його старійшині Тернохрусту.]===],
[===[Принесіть огневицю Леґаші старійшині Тернохрусту в Урсолан.]===],
nil,
nil,
},
[87295] = { en="Deflective Surface", ai=true,
[===[Відбивальна поверхня]===],
[===[Можливо, ти {стать:бачив:бачила} багрянокам'яних василісків, що блукають пустками за стінами, коли {стать:йшов:йшла} до фортеці Підсвітньої Варти. Це витривалі істоти, добре пристосовані до виживання в Спустошених землях. Одна з їхніх головних переваг — міцна луска, що відбиває жар, захищає від піску й вітру і навіть відхиляє удари зброї!

Це ідеальний матеріал для щитів, і якщо принесеш мені добрий оберемок, я щедро тобі заплачу. Тільки неси луску в доброму стані!]===],
[===[Принесіть 10 лусок багрянокам'яного василіска Берні Хейстену.]===],
nil,
nil,
},
[87346] = { en="Chieftain Bloodmaw", ai=true,
[===[Вождь Кровопащий]===],
[===[Коли Леґаші захопили Чорнопащих, решта Деревопузих запечатали прохід до свого оплоту, щоб не пустити сатирів. Ми й гадки не мали, що ті вижили як біженці.

Я б охоче допоміг своїм братам, але ми ведемо власні битви. Як Леґаші загрожують Чорнопащим, так само Мертволісі загрожують нам. У нас небагато воїнів, яких можна відрядити.

Вождь Мертволісих, Кровопащий, засів у селищі Сквернолапа на півдні. Якщо його усунути, нам стане значно легше. Принеси мені його булаву — і матимеш нашу допомогу.]===],
[===[Вбийте вождя Кровопащого та принесіть його булаву Ґорну Одноокому в оплот Деревопузих.]===],
nil,
nil,
},
[87494] = { en="Microcrystal Contamination", ai=true,
[===[Мікрокристалічне забруднення]===],
[===[Ця луска відбиває світло трохи сильніше й мерехтить райдужніше за інші, ніби в неї вкраплені крихітні частинки кристалів.

Можливо, Торва Слідопит зможе з'ясувати, що це таке.]===],
[===[Віднесіть насичену кристалами луску Торві Слідопиту.]===],
[===[Ун'Ґоро — це природа в її найдикішому й найнеприборканішому вигляді.]===],
[===[Яку дивну луску ти {стать:знайшов:знайшла}!

Схоже, ця істота проковтнула стільки кристалічного пилу, що він почав просочувати її луску. Мабуть, вона годувалася біля розбитого кристала, де пил потрапив у рослини, а потім — і в неї.

Підозрюю, що більші дози мали б глибокий і помітний вплив. Цьому звірові пощастило не проковтнути забагато.

Додам це до своєї колекції.]===],
},
[90487] = { en="Ancient Allies", ai=true,
[===[Древні союзники]===],
[===[{Ім'я:к}, більше мені нічого тобі запропонувати. Якщо ти маєш намір здолати довгий шлях на гору, варто поговорити з її древніми доглядачами.

Іди дорогою на захід. Дивись на північ, у бік підніжжя гори. Згодом ти побачиш заставу — залишок вартових, що колись блукали цими схилами. Там є древній на ім'я Ясен. Він і його друзі зможуть тобі допомогти.]===],
[===[Вирушайте на захід від печери відлюдника, щоб знайти заставу древніх і дріад на нижніх схилах гори Гіджал.]===],
nil,
nil,
},
[90647] = { en="The Staff of the Mountain", ai=true,
[===[Посох гори]===],
[===[Завдяки всім інгредієнтам, які ти {стать:зібрав:зібрала}, мені вдалося наповнити знайдений тобою посох новою магією. Тепер ти зможеш застосувати його проти магії Диких Богів, яку так зухвало викрав Ве'хан.

Втім, нам треба його випробувати. Віднеси посох друїдці на ім'я Тіала Білогрива на вершину Вічності. Можливо, вона зможе допомогти.]===],
[===[Принесіть посох гори Тіалі Білогривій на вершину Вічності.]===],
nil,
nil,
},
[90750] = { en="More Work?", ai=true,
[===[Знову робота?]===],
[===[Битви часто бувають довгими й запеклими, і ведуть у них ті, хто готовий протистояти неминучій загрозі й дивитися смерті в обличчя.

Правда в тому, що жертв було чимало, і не лише на полі бою. Ми часто не помічаємо тих, хто робить свій внесок.

Он там є робітник на ім'я... хоча, як подумати, я навіть не знаю його імені. Яка ж я після цього? Він увесь час, поки ми тут були, доглядав за нами й годував нас.

Можеш поговорити з ним? Скажи йому, що роботу зроблено.]===],
[===[Поговоріть з робітником і повідомте йому, що роботу зроблено.]===],
nil,
nil,
tasks = { ["Speak with the worker"] = [===[Поговорити з робітником]===] },
},
[90789] = { en="Scalebeard", ai=true,
[===[Лускобород]===],
[===[Часу обмаль, {ім'я:к}! Мої чари віщування виявили могутнє джерело магії. Я не можу покинути вежу, тож прошу тебе вбити мерзенну істоту, яка володіє цим артефактом.

Цього звіра звуть Лускобород, він ховається в печері біля затоки Штормів. Спопели його й забери призматичну мушлю з його лігва.]===],
[===[Добудьте призматичну мушлю для архімага Зілема. Архімаг мешкає у вежі на вершині скель Азшари.]===],
nil,
nil,
},
[90865] = { en="Eyes of the Watchers", ai=true,
[===[Очі наглядачів]===],
[===[Трохи на північ звідси лежать руїни минулих битв. Там досі лишаються рештки Скари, хоч їх і дедалі менше.

Хоча безтямні невмерлі й самі становлять загрозу, наглядачі пильно стежать за кожним, хто туди потрапляє, і через це позбутися загрози Скари ще важче.

Усунь цю загрозу, забравши в наглядачів те, що вони цінують найбільше.]===],
[===[Добудьте 8 очей наглядача для Елунет.]===],
nil,
nil,
},
[91696] = { en="Open Season", ai=true,
[===[Сезон полювання]===],
[===[Мертволісі напали на моє щеня і його батька. Він стояв твердо, бився до смерті, нас охороняв. Ми мусимо йти додому, але шлях темний і повний щелеп.

Тримайся поруч, охороняй нас добре. Я веду, ти відбиваєш, і ми доходимо до лігва цілі.]===],
[===[Проведіть матріарха Дубошкірих з лігва Мертволісих і поверніться до нори Дубошкірих.]===],
nil,
nil,
tasks = { ["Escort the Furbolg family out of Deadwood Den"] = [===[Провести родину хутропузів з лігва Мертволісих]===] },
},
[91697] = { en="Meet the Elders", ai=true,
[===[Знайомство зі старійшинами]===],
[===[Дякую, що {стать:допоміг:допомогла} зібрати ведмежі ягоди. Маленькі кроки будують довіру! Від тебе пахне ягідною смолою, тож старійшини мають прийняти тебе привітніше.

Іди й поговори зі старійшиною Туманною Лапою та старійшиною Сосномовцем.]===],
[===[Знайдіть старійшину Туманну Лапу та старійшину Сосномовця в норі Дубошкірих і поговоріть із ними.]===],
nil,
nil,
tasks = {
["Elder Pinespeaker met"] = [===[Старійшину Сосномовця зустрінуто]===],
["Elder Mistpaw met"] = [===[Старійшину Туманну Лапу зустрінуто]===],
},
},
[91698] = { en="Barkskin Breakout", ai=true,
[===[Втеча Дубошкірих]===],
[===[<Матріарх хутропузів звертається до вас із клітки>

"Мертволісі замкнули мене й моє дитинча в міцній клітці. Ключ висить на поясі мертволісого вартового. Ти полюй на них, бери ключ, піднімай засувку, випускай нас. Зробиш це - і Дубошкірі знатимуть, що серце в тебе щире."]===],
[===[Заберіть ключ Мертволісих у мертволісого вартового й поверніться до клітки Дубошкірих.]===],
nil,
nil,
},
[91754] = { en="Rub Some Dirt In It", ai=true,
[===[До весілля загоїться]===],
[===[Скільки років мені не траплялося {раса:р} на кшталт тебе!

Ох, не знаю, що й робити! Мій друг Ясен захворів, а я не можу лишити його самого!

Прошу, принеси мені трохи незіпсованого ґрунту з неоскверненої землі на південний схід звідси. Я зроблю припарки, які, може, допоможуть йому одужати.]===],
[===[Зберіть 6 зразків незіпсованого ґрунту в передгір'ях гори Гіджал.]===],
nil,
nil,
},
[91755] = { en="Leaves to Ligatures", ai=true,
[===[Від листя до перев'язок]===],
[===[Ти {стать:бачив:бачила} ті мерзенні заражені чагарники, що бродять цією долиною?

Ці рослини злі, але деякі з них не зовсім отруйні. Їхнє листя може мати цілющі властивості.

Будь {стать:ласкавий:ласкава}, принеси мені трохи зеленого листя. Звісно, доведеться трохи їх попідрізати.]===],
[===[Зберіть 12 одиниць зеленого листя із заражених чагарників у передгір'ях гори Гіджал.]===],
nil,
nil,
},
[91770] = { en="Bark Bite", ai=true,
[===[Болюча кора]===],
[===[З принесених тобою інгредієнтів я можу приготувати прості ліки. Ця припарка мала б допомогти Ясенові. Він старий, знаєш, і тяжко обгорів під час воєн. Його кора болить, а гілля ломить. Він мій найкращий друг, і я просто хочу, щоб йому полегшало!

Візьми цю припарку й щедро намасти нею всі місця, де його кора потріскалася, а з ран сочиться сік.]===],
[===[Прикладіть припарку до Ясена.]===],
nil,
nil,
tasks = { ["Fraxinus soothed"] = [===[Ясена заспокоєно]===] },
},
[91877] = { en="Demon Hunter's Hunter", ai=true,
[===[Мисливець за мисливцем на демонів]===],
[===[Небагато мисливців на демонів нині лишилося в Азероті, але дехто з нас і далі вистежує найнебезпечніші чи найпотаємніші загрози.

Мій колега, Меріон Телемахес, вирушив на Гіджал перевірити чутки про демонів у тих краях. Хоч у небезпечній ущелині Темного шепоту демонів чимало, є підозра, що демонів, які штурмували гору під час минулої війни, могли здолати не до кінця.

Це варто дослідити.]===],
[===[Знайдіть Меріона Телемахеса десь на горі Гіджал.]===],
nil,
nil,
},
[91882] = { en="The Grand Alliance", ai=true,
[===[Великий Альянс]===],
[===[Багато років тому Орда й Альянс відклали свої чвари, щоб разом дати відсіч більшій загрозі — Легіону. На горі Гіджал сили Великого Альянсу билися з Архімондом і його поплічниками, доки не зупинили їх.

Однак відступ із гори був небезпечним, і кількох сміливих бійців довелося залишити.

Тепер, коли шлях на велику гору знову відкритий, можливо, хтось із тих героїв досі живий у диких нетрях? Вирушай на гору Гіджал і не страшися її небезпек. З'ясуй, що сталося з нашими силами там.]===],
[===[Обшукайте гору Гіджал у пошуках решток Великого Альянсу.]===],
nil,
nil,
},
[91883] = { en="Spear of the Skylord", ai=true,
[===[Спис володаря неба]===],
[===[Під час сутички з червокрилими гарпіями на мене жорстоко напала з засідки гарпія на ім'я Заррат, що патрулює ці місця. Вона вихопила мій спис і полетіла з ним геть, не давши мені й оговтатися. Навіщо він їй знадобився — не можу сказати.

Цей спис передається в моїй родині з покоління в покоління і дуже багато для мене важить. Якщо помітиш Заррат серед гарпій, вбий її і поверни мені спис. Вона вміє ховатися, тож знайти її буде нелегко, але моїй вдячності не буде меж, якщо спис повернеться до мене.]===],
[===[Вбийте Заррат Червокрилу і поверніть спис Омнурона.]===],
nil,
nil,
},
