[91923] = { en="Celastrus the Bitter", ai=true,
[===[Целастр Гіркий]===],
[===[Гору заполонила дика поросль, роз'ятрена енергією скверни, що пролилася тут дощем так давно. Тепер бур'яни й рослини розлючені, споганені, отруєні.

На схилах на сході блукає великий терновий кущ на ім'я Целастр. Він убиває тварин, шмагає інші рослини, живиться тілами мертвих. Його треба знищити!

Бур'яни слід викорчувати, щоб гора могла знову зазеленіти.]===],
[===[Знайдіть і знищіть Целастра Гіркого та поверніться до Тилаєн з його зламаним пагоном.]===],
nil,
nil,
},
[91952] = { en="The Source of the Corruption", ai=true,
[===[Джерело порчі]===],
[===[Стільки порчі ллється згори на Сквернолісся. Коли з Гіджала прибуває вода, вона просякнута скверною. Скверна вбирається в землю й заражає дерева та рослини.

Колись у дикій глуші жив друїд, відлюдник на ім'я Кетарас, який глибоко знав цю гору. Якщо хтось і знає, що сталося на Гіджалі, то це він.

Гадаю, Сквернолісся не зцілиться, доки біду на Гіджалі не буде розв'язано.]===],
[===[Знайдіть відлюдника Кетараса на горі Гіджал.]===],
nil,
nil,
},
[92008] = { en="Premiere Parts", ai=true,
[===[Першокласні деталі]===],
[===[Ще одне нове обличчя?

Мені не варто дивуватися, зважаючи на силу наших так званих захисних чарів. Як там скверна внизу? Я вже кілька тижнів не виходила з цієї майстерні. Слухай, поки ти тут, у мене є кілька прохань, з якими ти, можливо, зможеш допомогти, якщо раптом захочеш побігати з дорученнями.

Ти не повіриш, як складно доставити путні деталі аж сюди, нагору, не кажучи вже про звичайні будівельні матеріали для інженерії. Намі в Завшегляді тримає для мене замовлення деталей. Як щодо зимової пробіжки?]===],
[===[Заберіть у Намі в Завшегляді замовлення деталей для Кайлени Шепоту Весни.]===],
nil,
nil,
},
[92009] = { en="Crate Expectations", ai=true,
[===[Ящик великих сподівань]===],
[===[Тобі слід дещо знати про це замовлення. На дні ящика лежить кілька інвертованих мана-елементів, обкладених м'якою підкладкою, наскільки мені вдалося. Ці елементи мають звичку розряджатися, якщо їх струснути і вчасно не стабілізувати. Вміст видихається десь за дві години.

Кайлена знатиме, що з ними робити, коли їх отримає, але раджу тобі не поспішати, якщо збираєшся верхи підійматися на гору Гіджал.

Якщо треба буде поповнити запас, повертайся, і я заправлю каністри. Тільки обережно, гаразд?]===],
[===[Обережно доставте ящик з деталями та дрібничками Кайлені Шепоту Весни на гору Гіджал.]===],
nil,
nil,
},
[92011] = { en="Rubble Rummage", ai=true,
[===[Порпання в руїнах]===],
[===[Мені знадобиться трохи часу, щоб розібратися, які креслення втілювати першими. А ще я давно збиралася піднятися до старої бази Орди й подивитися, які скарби можна змайструвати з того мотлоху, що там валяється.

Якщо ти прямуєш туди й маєш вільне місце в торбах, пильно шукай брухт, дріт чи грудки кажанячого... посліду! Що? Від нього теж є користь, ясно?!

Рештки табору Орди ти знайдеш високо на горі, навіть вище за поселення Пралісся.]===],
[===[Обнишпорте рештки бази Орди й принесіть Кайлені 5 потертих дротів, 5 шматків брухту та 5 грудок скам'янілого посліду.]===],
nil,
nil,
},
[92016] = { en="Rootwork", ai=true,
[===[Робота з корінням]===],
[===[Коріння Нордрассіля тягнеться далеко й глибоко — товще за річкові береги й старіше за пам'ять. Така велич несе й великий голод. У здорові часи воно п'є і тлін, і оновлення, черпаючи силу з нескінченного обертання природного циклу.

Та Гіджал зазнав ран, його ґрунт осквернила демонічна отрута.

Спустися в найглибші надра Колодязя Вічності. Уважно вивчи тамтешнє коріння. Ми мусимо знати, чи не ввібрало воно забагато скверни... чи, може, Світове Дерево ще вистоїть.]===],
[===[Увійдіть у Колодязь Вічності й огляньте коріння Нордрассіля.]===],
nil,
nil,
},
[92017] = { en="Cleansing Winds", ai=true,
[===[Очищувальні вітри]===],
[===[Летючі створіння вершини досі дихають повітрям найвищих потоків, куди порча ще не встигла повністю проникнути. Пір'я гіпогрифів і шерсть химер носяться цими вітрами, вбираючи те, що повітря пам'ятає про незаймані землі. Мені потрібні ці рештки, щоб закріпити й посилити силу моїх очисних пахощів.

Збери їх для мене, щоб я зміг зосередити знання вітру в очищувальному димі, перш ніж ми почнемо ритуал.]===],
[===[Зберіть 5 великих пір'їн гіпогрифа і 3 жмути маслянистої шерсті химери для Марна.]===],
nil,
nil,
},
[92020] = { en="Hol'anyee's Big Book of Big Lizards", ai=true,
[===[Велика книга великих ящерів Холанії]===],
[===[Я роблю нотатки й замальовки в альбомах про всіх створінь, що живуть у кратері Ун'Ґоро, і зробила кілька копій, щоб надіслати їх тим, кому це може бути цікаво!

Ось у мене є копія альбому, яку я давно хотіла передати друїдам на горі Гіджал, бо знаю, як вони люблять вивчати природу.

Щоправда, до Гіджала неблизький шлях. Може, візьмеш її з собою, якщо доведеться туди йти?]===],
[===[Віднесіть велику книгу великих ящерів Холанії друїдові на вершину гори Гіджал.]===],
nil,
nil,
},
[92065] = { en="Blackmaw Reclamation", ai=true,
[===[Чорнопащі повертають своє]===],
[===[Чи допоможеш ти нам у нашій останній битві, {раса:к}, і станеш {стать:спасителем:спасителькою} Чорнопащих?

Варрокс Похмуре Копито, прокляття Чорнопащих: демон, чия жага руйнування ніколи не вгамується. Його скверна поглинає все, чого торкається. Навіть зараз він і його поплічники далі спустошують наші нори.

Ми пройшли довгий шлях у боротьбі з Леґаші, але щоб Чорнопащі мали хоч якесь майбутнє, Варрокс мусить загинути.

Знайди його в оплоті Чорнопащих і зрази. Лише тоді Чорнопащі нарешті знайдуть спокій.]===],
[===[Принесіть голову Варрокса Похмурого Копита хранителю брами Лютореву в Урсолан.]===],
nil,
nil,
},
[92066] = { en="The Twin Bears", ai=true,
[===[Ведмеді-близнюки]===],
[===[Коли вторглися Леґаші, у метушні залишилося багато цінних речей. Найдорожчі для мене — два тотеми. На них зображено легенди про наших богів-близнюків, Урсока й Урсола.

Я знаю, що зараз найважливіше — вижити, але ми мусимо подбати й про збереження історії нашого народу.

Ці тотеми, найімовірніше, досі в нашому колишньому оплоті. Якщо так, ти зробиш велику ласку, повернувши їх мені.]===],
[===[Знайдіть тотем Урсока й тотем Урсола в оплоті Чорнопащих. Потім поверніть їх хранителю знань Ноку в Урсолан.]===],
nil,
nil,
},
[92067] = { en="Feeding Time!", ai=true,
[===[Час годування!]===],
[===[Ти, безперечно, {стать:довів мені, чого вартий:довела мені, чого варта}, {ім'я:к}, але інших з мого племені переконати не так легко. Для цього тобі доведеться й надалі боротися з Леґаші.

Принеси мені роги вбитих сатирів Леґаші. Кожна в'язка, яку ти мені принесеш, стане символом твого служіння Чорнопащим.]===],
nil,
nil,
nil,
},
[92069] = { en="Claws That Rend, Tusks that Gore", ai=true,
[===[Кігті, що роздирають, бивні, що протинають]===],
[===[Двоє велетнів патрулюють місце, яке Чорнопащі колись звали домом: Кісткорил Нескорений і Тлінопащ, великий ведмідь. Покоління мисливців намагалися їх повалити, і всі зазнали поразки.

Мені зовсім не до душі просити тебе вбити цих величних звірів, але мій народ мусить мати змогу повернутися додому. Найменше, що я можу зробити, — подбати, щоб їхня смерть не була марною. Якщо принесеш мені їхні рештки, я викую зброю на згадку про їхню силу.]===],
[===[Принесіть кігті великого ведмедя та бивні Нескореного Оґтінкові в Азшару.]===],
nil,
nil,
},
[92070] = { en="A Lost Memento", ai=true,
[===[Загублена пам'ятна річ]===],
[===[Намисто прикрашене різноманітними оберегами: клаптиками пір'я, жолудевими шкаралупками та барвистими камінцями. Його шкіряний ремінець порваний. Оздоблення свідчить, що воно належало хутропузові, а невеликий розмір і грубувата робота вказують на те, що його змайструвала дитина.

Цілком можливо, що для когось із Чорнопащих це намисто дороге як пам'ять. Добре було б знайти власника й повернути його.]===],
[===[Знайдіть власника намиста з пір'яним оберегом.]===],
nil,
nil,
},
[92100] = { en="Anywhere But Here", ai=true,
[===[Будь-де, тільки не тут]===],
[===[<Перед вами з'являється дух, який саме оговтується після позіху, що охопив його з голови до п'ят.>

З тобою немає війська... і вбрання на тобі не солдатське. Отже, ми таки відбили Архімонда?

Минуло стільки часу. Я майже забув, ким колись був, але ти... ти, мабуть, {стать:один:одна} з перших, хто ступає цими кратерами за багато років.

<Ветеран озирається довкола.>

Продовжмо нашу розмову на оглядовому майданчику трохи на захід звідси. Вид звідти я пам'ятаю дуже яскраво. Колись давно я залишив там свої піхви.]===],
[===[Знайдіть піхви ветерана Третьої війни біля Пралісся.]===],
nil,
nil,
},
[92101] = { en="Lifted by Legacy", ai=true,
[===[Піднесений спадщиною]===],
[===[Гіджал важко витримати. Серед кратерів досі витають кошмари та спогади про вбивства.

Але ти несеш у собі тепло Калімдору! Мій друг Тобін теж записався до війська й служив разом зі мною, але я боюся за його душу найгіршого.

Наша рота Альянсу видала нам скакунів, щоб ми об'їздили їх і здружилися з ними перед походом. Ми влаштували на них веселу прогулянку Степами. Вирізали свої імена внизу Великого Підйомника в Тисячі Шипів.

Подивишся, чи збереглися ті позначки? Це принесе розраду втомленій душі.]===],
[===[Знайдіть важливі позначки ветерана Третьої війни на Великому Підйомнику.]===],
nil,
nil,
},
[92102] = { en="Praise", ai=true,
[===[Хвала]===],
[===[Стільки зусиль лише заради останніх бажань загубленої душі, що вже згасає, — дякую тобі, {ім'я:к}. Присутності руки, яка вдумливо торкалася вирізаних знаків, і тих фрагментів історії, які ти вже знаєш, вистачило, щоб привести мене сюди. Тепер моя присутність прив'язана до найміцнішого зв'язку з тими, хто ще живий.

Я обігнав Тобіна дорогою до соляних рівнин, а він обставив мене на треку перегонів.

Тепер я пригадую ясніше. Зустрінь мене у Спочині Скорботи, там, де відбулася наша остання битва. Я чекатиму біля зламаної гармати неподалік від зруйнованої вежі на скелі.]===],
[===[Скористайтеся вишитими піхвами, щоб зустрітися з ветераном Третьої війни біля зламаної гармати у Спочині Скорботи, що на горі Гіджал.]===],
nil,
nil,
tasks = { ["Veteran of the Third War met in Mount Hyjal"] = [===[Ветерана Третьої війни зустрінуто на горі Гіджал]===] },
},
[92111] = { en="Of Friend and Fur", ai=true,
[===[Про друзів і хутро]===],
[===[Бачу, ти стараєшся, а старатися — більше, ніж роблять інші. Ми з часом даємо тобі добру волю, якщо ти теж так.

Заходь у наше лігво й говори з Осі. Вона має відкриті лапи, дасть тобі ще шанс допомогти.]===],
[===[Увійдіть до нори Дубошкірих і знайдіть хутропуза на ім'я Осі.]===],
nil,
nil,
},
[92147] = { en="Highfeather Helper", ai=true,
[===[На допомогу Високоперим]===],
[===[Я одна з останніх Високоперих, справжніх послідовників Авіани. Ми шануємо й вшановуємо Матір Небес, а Друїдів Кігтя звемо своїми союзниками.

Червокрилі гарпії заполонили більшу частину цього плато. Вони зрікаються нашої захисниці Авіани й прагнуть лише плюндрувати землі довкола нас.

Пролилася кров, і за неї треба відплатити. Розвій їхнє пір'я за вітром.]===],
[===[Вбийте 18 червокрилих гарпій на горі Гіджал і принесіть їхнє пір'я Фібі Високоперій.]===],
nil,
nil,
},
[92169] = { en="Paying Back the Pact", ai=true,
[===[Розплата з Пактом]===],
[===[Пакт Чорного Терну. Так вони себе називають. Друїди-відступники, що захопили вершину Гіджала. Жорстокі й непримиренні. Вони звинувачують Малфуріона Шаленство Бурі в тому, що він позбавив їх безсмертя, і поклялися повернути собі силу, від якої їх змусили відмовитися. Раніше я не розуміла магії, що наснажувала їх, але тепер усе стає ясно.

Візьми посох і застосуй його на друїдах Чорного Терну по всій горі. Він має відгукнутися на захисні чари, що їх оберігають, і розвіяти їх.]===],
[===[Застосуйте посох гори на 10 членах Пакту Чорного Терну на вершині Вічності, щоб зняти з них захисні чари, а тоді вбийте їх.]===],
nil,
nil,
tasks = {
["Slay Blackthorne Pact Members"] = [===[Вбити членів Пакту Чорного Терну]===],
["Test the Staff of the Mountain"] = [===[Випробувати посох гори]===],
},
},
[92171] = { en="Taking to New Heights", ai=true,
[===[На нові висоти]===],
[===[Щоб здолати Ве'хана, нам потрібен дотик неба. Крихта божественного — там, де звернене вгору обличчя прагне злетіти.

Вирушай до Святилища Авіани й розшукай володаря неба Омнурона. Як ватажок Друїдів Кігтя, він може допомогти додати дрібку благодаті Авіани.]===],
[===[Вирушайте до Святилища Авіани, що на горі Гіджал, і попросіть допомоги у володаря неба Омнурона.]===],
nil,
nil,
},
[92317] = { en="Stolen Life", ai=true,
[===[Вкрадене життя]===],
[===[Отже, друїд-самітник шукає силу, що врівноважила б «життя» в цій його магії? Тоді відповідь, звісно ж, смерть. Для такого це саме те місце.

Ти, безперечно, вже {стать:бачив:бачила} невмерлих, що повзають усіма моїми володіннями. Їх живить украдена сила, яка оживляє їх навіть у смерті.

Саме ця вкрадена сила й потрібна для чар, про які ти кажеш. Вбивай невмерлих і шукай у їхніх черепах згуслу краплю вкраденого життя. Щойно здобудеш її, віднеси Кетарасові.]===],
[===[Здобудьте краплю вкраденого життя у Скари в руїнах, що на горі Гіджал, а тоді поверніться до Кетараса.]===],
nil,
nil,
},
[92328] = { en="Siegecraft", ai=true,
[===[Облогове ремесло]===],
[===[З тими додатковими припасами, що ти {стать:приніс:принесла}, у мене вистачить матеріалів, щоб утілити початкові креслення Яелі для цього глефомета. Я лагоджу цю штуку вже... ну, здається, цілу вічність!

Якщо допоможеш і станеш мені другою парою рук, уся ця справа піде значно швидше! Я все тобі поясню крок за кроком, найскладніше, мабуть, уже позаду...

<Кайлена схрещує пальці на удачу.>

Привідна система й енергетичні елементи, що її живлять, майже налаштовані.]===],
[===[Поверніть дві шестерні й під'єднайте дві клеми батареї з обох боків глефомета Кайлени.]===],
nil,
nil,
tasks = {
