[94213] = { en="Craftsman's Writ: Lesser Mana Potion", ai=true,
[===[Замовлення майстра: Невелике зілля мани]===],
[===[<Записка, написана вицвілим чорнилом, замовляє 1 невелике зілля мани. У ній також указано місце доставки й оплату. Унизу зазначено, що це замовлення можна передати іншій особі.>]===],
[===[Здобудьте предмети, замовлені клієнтом, і доставте їх до місця, позначеного на вашій мапі. Щоб завершити угоду, це замовлення має бути при вас.]===],
[===[Добридень, {раса:к}. Мені приємне твоє товариство, але моя увага зараз деінде. Якщо в нас немає спільних справ, будь ласка, йди своєю дорогою.]===],
