nil,
nil,
},
[95599] = { en="The Old Key", ai=true,
[===[Старий ключ]===],
[===[<Ключ укритий товстим шаром іржі. Схоже, він доволі довго пролежав під водою.

Десь поблизу має бути замок, до якого він пасує, але вам доведеться його пошукати. Може, варто почати зі ставка на південний захід від цього табору?>]===],
[===[Знайдіть десь поблизу у Фераласі стару скриню, до якої пасує ключ.]===],
