tasks = { ["Remains buried"] = [===[Рештки поховано]===] },
},
[95751] = { en="Odd Totems", ai=true,
[===[Дивні тотеми]===],
[===[Духи явили мені видіння спеки, сонця й нескінченних хвилястих дюн. Пара самотніх різьблених тотемів, що височіють над кістками могутнього звіра, напівпохованими пісками часу. Мені явили пустельні пагорби Танарісу, у цьому я не сумніваюся.

Призначення цих тотемів мені невідоме, але їхня самотня варта напевно має якусь мету. Прошу тебе розшукати це місце й спробувати розгадати цю таємницю.]===],
[===[Дослідіть дивні тотеми в Танарісі.]===],
nil,
nil,
},
[95766] = { en="Fine Feathered Friend", ai=true,
[===[Пернатий друг]===],
[===[Цикл відродження нарешті почався. Древні... повстануть знову, і сила світу природи піде своїм шляхом... до розквіту.

Ти... {стать:допоміг:допомогла} нам схилити шальки терезів на користь природи. Можливо... ми ще зможемо вплинути сильніше... на значно тяжчу біду.

Рушай на захід... туди, де сама земля попеляста... і, можливо, знайдеш істоту, яка зможе допомогти. Вона може здаватися звичайною маленькою пташкою... але її сила велика.]===],
[===[Знайдіть дивну пташку на споганених землях південно-західного схилу.]===],
nil,
nil,
},
