[96060] = { en="Tempered Expectations", ai=true,
[===[Загартовані очікування]===],
[===[Скажу одразу: за життя я був майстром-мечником. Удень я кував зброю, а вночі орудував нею.

Як тобі добре відомо, мої стосунки з цим клинком тепер надзвичайно складні. Хоч я, мабуть, і зміг би ним помахати, не певен, що з нього буде багато користі, хіба що я битимусь з іншими духами. Хіба це справді має для мене якусь цінність у Шен'драласі?

Утім, я хотів би випробувати його можливості, та й, гадаю, нашим лісам не завадить легеньке проріджування.]===],
[===[Використайте примарний клинок, щоб стратити 8 диких звірів у Шен'драласі, а тоді поверніться до Віндаела в храм.]===],
nil,
[===[Чудово! Ба навіть видовищно! Після стількох років я радий почути, що цей меч бодай раз за все своє існування пролив кров.

А ті привиди, що тобі трапилися, - який несподіваний і чудернацький сюрприз. Це тішить мене менше, бо, найпевніше, означає, що нам доведеться вдруге винищувати тих самих істот, якщо вони примудрилися заплутатися в нашому світі духів.

Не те завдання, яким я хочу тебе обтяжувати, - принаймні не сьогодні. Займайся далі тим, чим ти тут займаєшся.]===],
tasks = { ["Shen'dralas wildlife slain with the blade"] = [===[Диких звірів Шен'драласу вбито клинком]===] },
},
[96063] = { en="Gaseous Gold", ai=true,
[===[Газоподібне золото]===],
[===[Паливо майбутнього — не вугілля і не нафта, а газ, крихітко! Оті болотяні ставки на південному заході вивергають його тоннами, і в мене якраз є винахід, щоб пустити його в діло, — двигун нового типу, що працює на цій штуці. Щоправда, збирати газ — справжній головний біль.

Якщо хочеш зробити скромний внесок у майбутнє науки та промисловості, чому б тобі не допомогти мені добути трохи того газу? Видно, як він здіймається з отворів біля води.]===],
[===[Зберіть 5 фіалів болотного газу для Слібо Шипоструя.]===],
[===[Сподіваюся, ти не проти, що в тонкощі свого винаходу я посвячуватиму тебе лише в міру потреби. Комерційні таємниці треба берегти, розумієш?]===],
[===[Чудово! Ці підійдуть просто супер. Ну, а що скажеш на ще одну-єдину послугу?]===],
},
[96067] = { en="Rock 'em and Sock 'em", ai=true,
[===[Тряси й лупцюй]===],
[===[Ти, {стать:мабуть, помітив:мабуть, помітила} мого механічного компаньйона, Г4З-М1Х. У його мішковинних грудях крутиться єдиний і неповторний робочий прототип мого газового двигуна.

Гадаю, його треба випробувати під навантаженням. Як щодо того, щоб зійтися з ним у бою? Я можу заправити його газом, який ти {стать:зібрав:зібрала}.

О, і не бійся завдати йому болю. Він нічого не відчуває!]===],
[===[Допоможіть Слібо випробувати його творіння.]===],
nil,
[===[Овва, ви двоє добряче зчепилися! Кращого видовища годі було й бажати, а ще я записав купу чудових нотаток.

Підлатаю старого Г4З і внесу кілька змін у двигун. Він вмить знову буде готовий до бою.

Тестуй, підкручуй, тестуй, підкручуй. Таке вже життя великого винахідника.]===],
tasks = { ["Fight G45-B4G in a stress test of Sleebo's engine."] = [===[Битися з Г4З-М1Х, випробовуючи двигун Слібо під навантаженням.]===] },
},
[96075] = { en="In Demand - Blackrock Legal Records", ai=true,
[===[Попит - юридичні записи Чорноскельної гори]===],
[===[Мої роботодавці хочуть прибрати до рук юридичні документи щодо права власності на Чорноскельну гору. Якась суперечка про майно. Хай там як, якщо ти здобудеш ці ключові записи, я зможу щедро тебе винагородити.

Здобудь мандат Нефаріана в генерала Драккісата у верхній частині Чорноскельного шпиля, ліцензію розпорядника у властителя Змійталака в нижній частині Чорноскельного шпиля та шлюбний договір Бронзобородих в імператора Тауріссана в Чорноскельних надрах.]===],
[===[Здобудьте мандат Нефаріана в генерала Драккісата в Чорноскельному шпилі, ліцензію розпорядника у властителя Змійталака в Чорноскельному шпилі та шлюбний договір Бронзобородих в імператора Тауріссана в Чорноскельних надрах і принесіть їх Пікс Ксіззікс у Грабіжну Бухту.]===],
nil,
nil,
},
[96076] = { en="In Demand - Ancient Elven Curiosities", ai=true,
[===[Попит - древні ельфійські раритети]===],
[===[Мої роботодавці хочуть прибрати до рук магічні раритети зі зруйнованого ельфійського міста Ельдре'Талас, нині відомого як Грізний Молот. Якісь магічні дослідження. Хай там як, якщо ти здобудеш ці предмети, я зможу щедро тебе винагородити.

Здобудь насіння Сквернолози в Альззіна-Диковертня у східному крилі, древню пам'ятку в принца Тортельдріна в західному крилі та мізиничний перстень із землекамінним діамантом у короля Ґордока в північному крилі.]===],
[===[Вирушайте до Грізного Молота, щоб здобути насіння Сквернолози в Альззіна-Диковертня, древню пам'ятку в принца Тортельдріна та мізиничний перстень із землекамінним діамантом у короля Ґордока, і принесіть їх Пікс Ксіззікс у Грабіжну Бухту.]===],
nil,
nil,
},
[96087] = { en="In Demand - Plague Records", ai=true,
[===[Попит: записи про Чуму]===],
[===[Група істориків найняла мене, щоб я роздобула записи про велику Чуму. Хочуть довести, хто винен, а хто ні, чи щось таке. Добудь для мене кілька цих записів, і я щедро тебе винагороджу.

Забери записи директора в темного магістра Ґандлінґа в Некроситеті, записи про постачання зерна в барона Рівендера в охопленому вічним полум'ям місті Стратгольмі та листи Датрогана у верховного лицаря Сайдана Датрогана в Багряному бастіоні Стратгольма.]===],
[===[Здобудьте записи директора в темного магістра Ґандлінґа, записи про постачання зерна в барона Рівендера та листи Датрогана у верховного лицаря Сайдана Датрогана й принесіть їх Пікс Ксіззікс у Грабіжну Бухту.]===],
nil,
nil,
},
[96088] = { en="In Demand - Titan Relics", ai=true,
[===[Попит: реліквії титанів]===],
[===[Якісь дослідники з Даларана шукають реліквії титанів та їхніх послідовників, а також їхніх ворогів із Палаючого Легіону. Реліквії лежать у таких підступних місцях, куди мені не дістатися. Добудь їх для мене, і я щедро тебе винагороджу.

Забери сльозу Ізери в Тіні Ераніка в храмі Атал'Гаккар, знак Ксавія у Варрокса Похмурого Копита в оплоті Чорнопащих і сигілу Фреї в Нанаї на терасі Творця.]===],
[===[Здобудьте сльозу Ізери в Тіні Ераніка в Затонулому храмі, знак Ксавія у Варрокса Похмурого Копита в оплоті Чорнопащих і сигілу Фреї в Нанаї на терасі Творця й принесіть їх Пікс Ксіззікс у Грабіжну Бухту.]===],
nil,
nil,
},
[96101] = { en="The Great Outdoors", ai=true,
[===[На лоні природи]===],
[===[Вітаю, {клас:к}. Бачу, ти маєш вигляд {стать:справжнього шукача пригод:справжньої шукачки пригод}. Це добре. Світові потрібно більше таких неспокійних душ, як ми, що шукають статків і слави.

