tasks = { ["Win 10 duels"] = [===[Перемогти в 10 дуелях]===] },
},
[96913] = { en="Field of Honor: Week 2", ai=true,
[===[Поле честі: тиждень 2]===],
[===[Знову ти, га? {стать:Готовий:Готова} до наступного випробування? Сподіваюся, вигляд крові тебе не лякає. Можливо, цього разу доведеться пролити власну кров... а краще спершу пустити кров супротивникам.]===],
[===[Завершіть 3 битви в тіснині Пісні Війни.]===],
